package com.tainted.community.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.nullValue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts (handler: listPosts)
 *
 * Pure HTTP + direct JDBC test. No internal classes are imported, no {@code @MockBean}/
 * {@code @SpringBootTest} is used. The target server and its real MySQL database must already
 * be running (see BASE_URL / DB_URL system properties).
 *
 * No WireMock stubs are used by this endpoint: {@code detect-external-calls --include-di-analysis}
 * found zero HTTP-based external calls reachable from {@code listPosts} (see
 * .nimbus/artifacts/detect-external-calls/CommunityController_listPosts.json). The only outbound
 * integration in this service (Kafka, via CommunityEventPublisher) is not used by listPosts at all,
 * and is non-HTTP in any case, so it is out of WireMock's scope per pipeline Core Principle #4.
 *
 * Checklist cross-reference (.nimbus/artifacts/test-plan/CommunityService_listPosts.md):
 *  - NTC_branch_listPosts_1 (Happy Path) -> covered by all NTC_* methods below.
 *  - ATC_code400 (General Bad Request) -> NOT IMPLEMENTED. GET /internal/posts takes no request
 *    parameters, path variables, or body, so there is no user-controlled input capable of
 *    triggering MethodArgumentNotValidException / HttpMessageNotReadableException. This is a
 *    heuristic checklist entry that does not apply to a zero-input endpoint; documented here
 *    rather than silently dropped or faked with an unreachable assertion.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class InternalPostsListBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/community");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        return String.format("T%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static byte[] readAll(InputStream is) throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] data = new byte[4096];
        int nRead;
        while ((nRead = is.read(data, 0, data.length)) != -1) {
            buffer.write(data, 0, nRead);
        }
        return buffer.toByteArray();
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = InternalPostsListBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(readAll(is), StandardCharsets.UTF_8);
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static Map<String, String> postParams(String postId, String userId, String title, String category,
                                                    String content, String moodEmojiLiteral, String nickname,
                                                    int likes, String createdAt) {
        Map<String, String> m = new LinkedHashMap<String, String>();
        m.put("POST_ID", postId);
        m.put("USER_ID", userId);
        m.put("TITLE", title);
        m.put("CATEGORY", category);
        m.put("CONTENT", content);
        m.put("MOOD_EMOJI_LITERAL", moodEmojiLiteral);
        m.put("NICKNAME", nickname);
        m.put("LIKES", String.valueOf(likes));
        m.put("CREATED_AT", createdAt);
        return m;
    }

    @Test
    void NTC_listPosts_orderedByCreatedAtDesc(TestInfo info) throws Exception {
        String uid = testId(info) + "-user";
        String id1 = testId(info) + "-1";
        String id2 = testId(info) + "-2";
