package com.tainted.community.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.LinkedHashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api POST /internal/posts (handler: createPost)
 *
 * Pure HTTP + direct JDBC test. No internal classes are imported and no in-process Spring test
 * annotations or bean mocking are used.
 *
 * No WireMock stubs: detect-external-calls found zero HTTP-based external calls reachable from
 * createPost (.nimbus/artifacts/detect-external-calls/CommunityController_createPost.json).
 * createPost does publish two Kafka events (post.created, mood.logged) via CommunityEventPublisher,
 * but KafkaTemplate#send() is fire-and-forget (no blocking .get()) and Kafka is not an HTTP
 * integration, so it is both unobservable from this HTTP+JDBC-only test and out of WireMock's
 * scope per pipeline Core Principle #4.
 *
 * Checklist cross-reference (.nimbus/artifacts/test-plan/CommunityService_createPost.md):
 *  - NTC_branch_createPost_1 (Happy Path) -> covered by NTC_* methods below.
 *  - ATC_code400 (General Bad Request) -> covered by the VTC_*_EMPTY / VTC_userId_NULL /
 *    VTC_content_WHITE_SPACE methods below, which trigger MethodArgumentNotValidException -> 400.
 *    These VTC cases are manually derived (not auto-generated by extract-key-params, which only
 *    inspects branch conditions inside the service method body and therefore cannot see the
 *    @NotBlank constraints declared on CreatePostRequest) per pipeline Step 3-A guidance:
 *    "Validation annotations(@NotNull, @Size)이 있으면 VTC 테스트 케이스에 반영".
 *
 * LENGTH_EXCEEDED was intentionally NOT added for title/category/content/nickname/userId: none of
 * these fields carry a @Size constraint, so an over-length value passes Bean Validation and would
 * only fail (or silently truncate) at the MySQL column-length boundary depending on the server's
 * sql_mode (STRICT_TRANS_TABLES vs not) -- a live-DB-config detail this run has no access to
 * verify (no DB connection is available while authoring these tests). Asserting a specific status
 * code here would be a guess, which violates the zero-hallucination requirement, so this case is
 * documented as not implementable rather than faked.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class InternalPostsCreateBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8085");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/community");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        return String.format("T%09d", Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static byte[] readAll(InputStream is) throws Exception {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] data = new byte[4096];
        int nRead;
        while ((nRead = is.read(data, 0, data.length)) != -1) {
            buffer.write(data, 0, nRead);
        }
        return buffer.toByteArray();
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = InternalPostsCreateBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(readAll(is), StandardCharsets.UTF_8);
            for (Map.Entry<String, String> entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private static void teardownByPostId(String postId) {
        Map<String, String> m = new LinkedHashMap<String, String>();
        m.put("POST_ID", postId);
        executeSqlTemplate("sql/internal-posts-create-teardown.sql", m);
    }

    private static String createPostBody(String userId, String title, String category, String content,
                                          String moodEmoji, String nickname) {
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        appendField(sb, "userId", userId);
        sb.append(",");
        appendField(sb, "title", title);
        sb.append(",");
        appendField(sb, "category", category);
        sb.append(",");
        appendField(sb, "content", content);
        sb.append(",");
        appendNullableField(sb, "moodEmoji", moodEmoji);
        sb.append(",");
        appendField(sb, "nickname", nickname);
        sb.append("}");
        return sb.toString();
    }

    private static void appendField(StringBuilder sb, String name, String value) {
        if (value == null) {
            sb.append("\"").append(name).append("\":null");
        } else {
            sb.append("\"").append(name).append("\":\"").append(value.replace("\"", "\\\"")).append("\"");
        }
    }

    private static void appendNullableField(StringBuilder sb, String name, String value) {
        appendField(sb, name, value);
    }

    @Test
    void NTC_createPost_success(TestInfo info) throws Exception {
        String id = testId(info);
        String userId = "user-" + id;

        String body = createPostBody(userId, "새 게시글 제목", "career", "새 게시글 본문 내용입니다.", "😊", "닉네임-" + id);

        String postId = given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(body)
        .when()
            .post("/internal/posts")
        .then().log().all()
            .statusCode(201)
            .contentType(ContentType.JSON)
            .body("postId", matchesPattern("^[0-9a-fA-F-]{36}$"))
            .extract().path("postId");

        try {
            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                    "SELECT user_id, title, category, content, mood_emoji, nickname, likes FROM post WHERE id = ?")) {
                ps.setString(1, postId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(userId, rs.getString("user_id"));
                assertEquals("새 게시글 제목", rs.getString("title"));
                assertEquals("career", rs.getString("category"));
                assertEquals("새 게시글 본문 내용입니다.", rs.getString("content"));
                assertEquals("😊", rs.getString("mood_emoji"));
                assertEquals("닉네임-" + id, rs.getString("nickname"));
                assertEquals(0, rs.getInt("likes"));
            }
        } finally {
            teardownByPostId(postId);
        }
    }

    @Test
    void NTC_createPost_withoutMoodEmoji(TestInfo info) throws Exception {
        String id = testId(info);
        String userId = "user-" + id;

        String body = createPostBody(userId, "무드 없는 글", "daily", "무드 이모지 없이 작성", null, "무드없음-" + id);

        String postId = given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(body)
        .when()
            .post("/internal/posts")
        .then().log().all()
            .statusCode(201)
            .body("postId", matchesPattern("^[0-9a-fA-F-]{36}$"))
            .extract().path("postId");

        try {
            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                    "SELECT mood_emoji, category, likes FROM post WHERE id = ?")) {
                ps.setString(1, postId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertNull(rs.getString("mood_emoji"));
                assertEquals("daily", rs.getString("category"));
                assertEquals(0, rs.getInt("likes"));
            }
        } finally {
            teardownByPostId(postId);
        }
    }

    @Test
    void NTC_createPost_mentalCategory(TestInfo info) throws Exception {
        String id = testId(info);
        String userId = "user-" + id;

        String body = createPostBody(userId, "멘탈 카테고리 글", "mental", "멘탈 카테고리 본문", "😢", "멘탈닉-" + id);

        String postId = given().log().all()
            .baseUri(BASE_URL)
            .contentType(ContentType.JSON)
            .body(body)
        .when()
            .post("/internal/posts")
        .then().log().all()
            .statusCode(201)
            .extract().path("postId");

        try {
            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement(
                    "SELECT category, mood_emoji, title FROM post WHERE id = ?")) {
                ps.setString(1, postId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals("mental", rs.getString("category"));
