                .statusCode(200)
                .body("postId", equalTo(id))
                .body("likes", equalTo(1));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement("SELECT likes FROM post WHERE id = ?")) {
                ps.setString(1, id);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(1, rs.getInt("likes"));
            }
        } finally {
            executeSqlTemplate("sql/internal-posts-like-teardown.sql", singleId(id));
        }
    }

    @Test
    void NTC_like_incrementsFromNonZero(TestInfo info) throws Exception {
        String id = testId(info);
        String uid = id + "-user";

        executeSqlTemplate("sql/internal-posts-like-teardown.sql", singleId(id));
        executeSqlTemplate("sql/internal-posts-like-setup.sql",
                postParams(id, uid, "좋아요 10글", "daily", "본문", "NULL", "닉네임2", 10, "2023-02-02 00:00:00"));

        try {
            given().log().all()
                .baseUri(BASE_URL)
                .pathParam("id", id)
            .when()
                .post("/internal/posts/{id}/like")
            .then().log().all()
                .statusCode(200)
                .body("postId", equalTo(id))
                .body("likes", equalTo(11));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement("SELECT likes FROM post WHERE id = ?")) {
                ps.setString(1, id);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(11, rs.getInt("likes"));
            }
        } finally {
            executeSqlTemplate("sql/internal-posts-like-teardown.sql", singleId(id));
        }
    }

    @Test
    void NTC_like_multipleCallsAccumulate(TestInfo info) throws Exception {
        String id = testId(info);
        String uid = id + "-user";

        executeSqlTemplate("sql/internal-posts-like-teardown.sql", singleId(id));
        executeSqlTemplate("sql/internal-posts-like-setup.sql",
                postParams(id, uid, "연속 좋아요 글", "mental", "본문", "'🔥'", "닉네임3", 0, "2023-03-03 00:00:00"));

        try {
            given().baseUri(BASE_URL).pathParam("id", id).when().post("/internal/posts/{id}/like")
                .then().statusCode(200).body("likes", equalTo(1));
            given().baseUri(BASE_URL).pathParam("id", id).when().post("/internal/posts/{id}/like")
                .then().statusCode(200).body("likes", equalTo(2));
            given().log().all()
                .baseUri(BASE_URL)
                .pathParam("id", id)
            .when()
                .post("/internal/posts/{id}/like")
            .then().log().all()
                .statusCode(200)
                .body("postId", equalTo(id))
                .body("likes", equalTo(3));

            try (Connection conn = getDbConnection();
                 PreparedStatement ps = conn.prepareStatement("SELECT likes FROM post WHERE id = ?")) {
                ps.setString(1, id);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(3, rs.getInt("likes"));
            }
        } finally {
            executeSqlTemplate("sql/internal-posts-like-teardown.sql", singleId(id));
        }
    }

    @Test
    void ATC_postId_notFound(TestInfo info) throws Exception {
        String id = "nonexistent-" + testId(info);

        given().log().all()
            .baseUri(BASE_URL)
            .pathParam("id", id)
        .when()
            .post("/internal/posts/{id}/like")
        .then().log().all()
            .statusCode(404)
            .contentType("application/problem+json")
            .body("title", equalTo("Post not found"))
            .body("detail", equalTo("post not found: " + id));
    }

    @Test
    void VTC_postId_WHITE_SPACE(TestInfo info) throws Exception {
        String id = " ";

        given().log().all()
            .baseUri(BASE_URL)
            .pathParam("id", id)
        .when()
            .post("/internal/posts/{id}/like")
        .then().log().all()
            .statusCode(404)
            .contentType("application/problem+json")
            .body("detail", equalTo("post not found: " + id));
    }

    @Test
    void VTC_postId_SPECIAL_CHAR(TestInfo info) throws Exception {
        String id = "'; DROP TABLE post; --";

        given().log().all()
            .baseUri(BASE_URL)
            .pathParam("id", id)
        .when()
            .post("/internal/posts/{id}/like")
        .then().log().all()
            .statusCode(404)
            .contentType("application/problem+json")
            .body("detail", equalTo("post not found: " + id));
    }

    @Test
    void VTC_postId_LENGTH_EXCEEDED(TestInfo info) throws Exception {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 75; i++) {
            sb.append('y');
        }
        String id = sb.toString();

        given().log().all()
            .baseUri(BASE_URL)
            .pathParam("id", id)
        .when()
            .post("/internal/posts/{id}/like")
        .then().log().all()
            .statusCode(404)
            .contentType("application/problem+json")
            .body("detail", equalTo("post not found: " + id));
    }
}

